// Golden values of the Home for the 8 personas (docs/spec/03 §1.2, docs/spec/00 §8.8): the DAL + domain builders over the
// seeded in-memory database reproduce the prototype's renderValsEN() / renderVals() output. The fixture
// (src/features/home/home.golden.json) was generated by evaluating the prototype logic in its default state
// (project HLT-026, no zone, no overrides) for every role, in EN and FR.
import { beforeAll, describe, expect, it } from 'vitest';
import { PERSONA_BY_ROLE } from '@/config/personas';
import type { RoleKey } from '@/config/screens';
import { renderTxt, type HomeView, type Txt } from '@/domain/home';
import golden from '@/features/home/home.golden.json';
import { makeT, type Lang } from '@/i18n/translate';
import { setDb } from '@/server/db/client';
import { openDatabase } from '@/server/db/open';
import type { ZoneKey } from '@/server/session';
import { recordEcoProgress } from './eco';
import { getHomeView } from './home';
import { getProject } from './projects';
import { createDraftPurchaseOrders } from './purchasing';
import { decideDeliverable } from './quality';

type Kpi = [string, string, string, boolean];
type Golden = { greeting: string; sub: string; kpis: (Kpi | null)[]; lt: string; lr: string[][]; rt: string; rr: string[][] };
const G = golden as unknown as Record<RoleKey, Record<Lang, Golden>>;
const ROLES: RoleKey[] = ['director', 'pm', 'depthead', 'member', 'englead', 'quality', 'procurement', 'client'];

async function render(role: RoleKey, lang: Lang, projectCode = 'HLT-026', zone: ZoneKey | null = null, organisation = PERSONA_BY_ROLE[role].organisation) {
  const p = PERSONA_BY_ROLE[role];
  const view: HomeView = await getHomeView({ role, persona: { name: p.name, title: p.title }, projectCode, zone, lang, organisation });
  const tx = (x: Txt) => renderTxt(x, makeT(lang));
  const out: Golden = {
    greeting: tx(view.greeting), sub: tx(view.sub),
    kpis: view.kpis.map((k) => [tx(k.label), tx(k.value), tx(k.sub), k.lo]),
    lt: tx(view.left.title), lr: view.left.rows.map((r) => [tx(r.title), tx(r.sub), tx(r.tag), r.tagClass]),
    rt: tx(view.right.title), rr: view.right.rows.map((r) => [tx(r.title), tx(r.sub), tx(r.tag), r.tagClass]),
  };
  return { view, out };
}

/** Deliberate departures from the prototype FR output: strings it left in English (docs/spec/01 §13.4). */
const FR_FIXES: [string | RegExp, string][] = [
  ['Department heads · 4 ouvertes', 'Chefs de service · 4 ouvertes'],
  [/— Harbor Line Terminal Expansion$/, '— Extension du terminal Harbor Line'],
  [/· Harbor Line Terminal Expansion$/, '· Extension du terminal Harbor Line'],
  [/^Contract structural engineer · /, 'Ingénieur structure intérimaire · '],
  ['Schedule slip −27 d · BL2 to submit to the change control board', 'Glissement du planning −27 j · BL2 à soumettre au comité de contrôle des modifications'],
  ['File d’approbation — Engineering', 'File d’approbation — Ingénierie'],
  ['Pending review', 'En attente d’examen'],
  ['En tant que Engineering lead', 'En tant que Référent ingénierie'],
  [/ at level ≥3$/, ' au niveau ≥3'],
  ['ECOs awaiting quality', 'ECO en attente qualité'],
  ['ISO 9001 review', 'Revue ISO 9001'],
  ['Inspections requested', 'Inspections demandées'],
  ['Pending department approval', 'En attente d’approbation du service'],
  ['BOM not yet ordered', 'Nomenclature non commandée'],
  ['ECOs touching open POs', 'ECO touchant des commandes ouvertes'],
  [/ · Forecast /, ' · Prévision '],
  ['+85 k€ · schedule recovery 12 jours · submitted 24 sept.', '+85 k€ · rattrapage de 12 jours · soumise le 24 sept.'],
  [/^Test & inspection reports · /, 'Rapports d’essais et d’inspection · '],
  [/^Manuals \/ as-built · /, 'Manuels / plans de récolement · '],
  [/^Calculation notes · /, 'Notes de calcul · '],
];
const fixFr = (s: string) => FR_FIXES.reduce((acc, [from, to]) => (typeof from === 'string' ? (acc === from ? to : acc) : acc.replace(from, to)), s);
const mapStrings = <T,>(v: T, f: (s: string) => string): T =>
  (typeof v === 'string' ? f(v) : Array.isArray(v) ? v.map((x) => mapStrings(x, f)) : v && typeof v === 'object' ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, mapStrings(x, f)])) : v) as T;

